* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const isProduction = api.context.props.experienceProperties.environment.value === 'production';
	return {
		event: 'Complete step',
		value: {
			Environment: isProduction ? 'Production' : 'Subproduction',
			Skipped: true,
			Step: 'Review Skipped Records'
		}
	};
})

