javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	const skipsWithTests = parseInt(api.state.totalSkippedRecords) - parseInt(api.state.skippedRecordsWithoutTests);
	return {
		event: 'Review post upgrade skipped records',
		value: {
			'Session id': api.state.upgradeSessionId,
			'Skip count': parseInt(api.state.totalSkippedRecords),
			'Test count': skipsWithTests,
			'Resolved count': parseInt(api.state.skippedResolved)
		}
	};
})

